-- CampCount initial schema.
-- Conventions:
--   * ids are TEXT UUIDs generated by the application (scans: by the device).
--   * timestamps are UTC ISO-8601 strings ('2026-12-05T09:30:00.000Z').
--   * every event-scoped table carries event_id, and queries always filter on it.
--   * tables marked SENSITIVE are purged by the retention job.

PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------- accounts

CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  display_name  TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE login_challenges (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  code_hash        TEXT NOT NULL,
  link_token_hash  TEXT NOT NULL UNIQUE,
  attempts         INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL,
  expires_at       TEXT NOT NULL,
  consumed_at      TEXT
);
CREATE INDEX login_challenges_user ON login_challenges (user_id, created_at);

-- ---------------------------------------------------------------- roles

-- Permissions are defined in code (src/shared/permissions.ts); roles are data.
CREATE TABLE roles (
  id           TEXT PRIMARY KEY,
  key          TEXT NOT NULL UNIQUE,
  name         TEXT NOT NULL,
  description  TEXT NOT NULL DEFAULT '',
  scope        TEXT NOT NULL CHECK (scope IN ('platform', 'event', 'activity')),
  is_system    INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0, 1)),
  created_at   TEXT NOT NULL
);

CREATE TABLE role_permissions (
  role_id     TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  permission  TEXT NOT NULL,
  PRIMARY KEY (role_id, permission)
);

-- ---------------------------------------------------------------- events

CREATE TABLE events (
  id                    TEXT PRIMARY KEY,
  slug                  TEXT NOT NULL UNIQUE,
  name                  TEXT NOT NULL,
  description           TEXT NOT NULL DEFAULT '',
  location              TEXT NOT NULL DEFAULT '',
  starts_on             TEXT NOT NULL,           -- local date YYYY-MM-DD
  ends_on               TEXT NOT NULL,
  timezone              TEXT NOT NULL DEFAULT 'Australia/Adelaide',
  status                TEXT NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft', 'open', 'completed', 'archived', 'cancelled')),
  feature_activities    INTEGER NOT NULL DEFAULT 1 CHECK (feature_activities IN (0, 1)),
  feature_meals         INTEGER NOT NULL DEFAULT 0 CHECK (feature_meals IN (0, 1)),
  feature_site          INTEGER NOT NULL DEFAULT 0 CHECK (feature_site IN (0, 1)),
  feature_dietary       INTEGER NOT NULL DEFAULT 0 CHECK (feature_dietary IN (0, 1)),
  feature_photo         INTEGER NOT NULL DEFAULT 1 CHECK (feature_photo IN (0, 1)),
  feature_self_signup   INTEGER NOT NULL DEFAULT 0 CHECK (feature_self_signup IN (0, 1)),
  -- Random key for fingerprinting source dietary text on import (change detection only).
  fingerprint_key       TEXT NOT NULL DEFAULT (lower(hex(randomblob(32)))),
  created_by            TEXT NOT NULL REFERENCES users(id),
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL,
  closed_at             TEXT,
  CHECK (ends_on >= starts_on)
);

CREATE TABLE activities (
  id                 TEXT PRIMARY KEY,
  event_id           TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name               TEXT NOT NULL,
  description        TEXT NOT NULL DEFAULT '',
  location           TEXT NOT NULL DEFAULT '',
  instructions       TEXT NOT NULL DEFAULT '',
  starts_at          TEXT,
  ends_at            TEXT,
  capacity           INTEGER CHECK (capacity IS NULL OR capacity > 0),
  capacity_policy    TEXT NOT NULL DEFAULT 'warn' CHECK (capacity_policy IN ('warn', 'block')),
  track_sign_out     INTEGER NOT NULL DEFAULT 0 CHECK (track_sign_out IN (0, 1)),
  allow_repeat       INTEGER NOT NULL DEFAULT 1 CHECK (allow_repeat IN (0, 1)),
  booking_required   INTEGER NOT NULL DEFAULT 0 CHECK (booking_required IN (0, 1)),
  signup_open        INTEGER NOT NULL DEFAULT 0 CHECK (signup_open IN (0, 1)),
  status             TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'cancelled')),
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL
);
CREATE INDEX activities_event ON activities (event_id);

CREATE TABLE meal_services (
  id          TEXT PRIMARY KEY,
  event_id    TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  location    TEXT NOT NULL DEFAULT '',
  starts_at   TEXT,
  ends_at     TEXT,
  status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'cancelled')),
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
CREATE INDEX meal_services_event ON meal_services (event_id);

-- Assignment of a role to a user. event_id is NULL only for platform roles;
-- activity_id narrows an activity-scoped role to one activity.
CREATE TABLE assignments (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role_id      TEXT NOT NULL REFERENCES roles(id),
  event_id     TEXT REFERENCES events(id) ON DELETE CASCADE,
  activity_id  TEXT REFERENCES activities(id) ON DELETE CASCADE,
  created_by   TEXT REFERENCES users(id),
  created_at   TEXT NOT NULL,
  revoked_at   TEXT,
  revoked_by   TEXT REFERENCES users(id),
  CHECK (activity_id IS NULL OR event_id IS NOT NULL)
);
CREATE UNIQUE INDEX assignments_active_unique
  ON assignments (user_id, role_id, COALESCE(event_id, ''), COALESCE(activity_id, ''))
  WHERE revoked_at IS NULL;
CREATE INDEX assignments_user ON assignments (user_id) WHERE revoked_at IS NULL;
CREATE INDEX assignments_event ON assignments (event_id) WHERE revoked_at IS NULL;

-- ---------------------------------------------------------------- stations & sessions

-- A shared device paired to exactly one scanning context.
CREATE TABLE stations (
  id                  TEXT PRIMARY KEY,
  event_id            TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name                TEXT NOT NULL,
  context_type        TEXT NOT NULL CHECK (context_type IN ('activity', 'meal', 'site')),
  context_id          TEXT,
  pairing_code_hash   TEXT UNIQUE,
  pairing_expires_at  TEXT,
  paired_at           TEXT,
  expires_at          TEXT NOT NULL,
  created_by          TEXT NOT NULL REFERENCES users(id),
  created_at          TEXT NOT NULL,
  revoked_at          TEXT,
  CHECK ((context_type = 'site') = (context_id IS NULL))
);
CREATE INDEX stations_event ON stations (event_id);

CREATE TABLE sessions (
  id_hash          TEXT PRIMARY KEY,
  user_id          TEXT REFERENCES users(id) ON DELETE CASCADE,
  station_id       TEXT REFERENCES stations(id) ON DELETE CASCADE,
  created_at       TEXT NOT NULL,
  last_seen_at     TEXT NOT NULL,
  expires_at       TEXT NOT NULL,
  revoked_at       TEXT,
  CHECK ((user_id IS NULL) <> (station_id IS NULL))
);
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_station ON sessions (station_id);

-- ---------------------------------------------------------------- people

-- Organisation-level identity. Deliberately minimal and non-sensitive.
CREATE TABLE people (
  id              TEXT PRIMARY KEY,
  member_number   TEXT NOT NULL UNIQUE,
  first_name      TEXT NOT NULL,
  preferred_name  TEXT NOT NULL DEFAULT '',
  last_name       TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

-- A person's participation in one event.
CREATE TABLE registrations (
  id                    TEXT PRIMARY KEY,
  event_id              TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  person_id             TEXT NOT NULL REFERENCES people(id),
  kind                  TEXT NOT NULL CHECK (kind IN ('youth', 'adult')),
  section               TEXT NOT NULL DEFAULT '',
  group_name            TEXT NOT NULL DEFAULT '',
  position              TEXT NOT NULL DEFAULT '',
  role_label            TEXT NOT NULL DEFAULT '',
  team                  TEXT NOT NULL DEFAULT '',
  source_status         TEXT NOT NULL DEFAULT '',
  photo_consent         TEXT NOT NULL DEFAULT 'unknown' CHECK (photo_consent IN ('yes', 'no', 'unknown')),
  status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'withdrawn')),
  dietary_source_hash   TEXT,   -- hash of source text, to detect changes on re-import; never the text itself
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL,
  UNIQUE (event_id, person_id)
);
CREATE INDEX registrations_event ON registrations (event_id, status);

-- SENSITIVE: structured dietary requirements, no free-form medical text.
CREATE TABLE dietary_entries (
  id               TEXT PRIMARY KEY,
  event_id         TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  registration_id  TEXT NOT NULL REFERENCES registrations(id) ON DELETE CASCADE,
  category         TEXT NOT NULL CHECK (category IN ('allergy', 'intolerance', 'medical_diet', 'religious_cultural', 'preference')),
  item             TEXT NOT NULL,
  severity         TEXT NOT NULL DEFAULT 'standard' CHECK (severity IN ('standard', 'anaphylactic')),
  note             TEXT NOT NULL DEFAULT '' CHECK (length(note) <= 80),
  created_by       TEXT NOT NULL REFERENCES users(id),
  created_at       TEXT NOT NULL
);
CREATE INDEX dietary_entries_registration ON dietary_entries (registration_id);
CREATE INDEX dietary_entries_event ON dietary_entries (event_id);

-- QR credential. Scans are matched on token_hash; the token itself is kept
-- only encrypted (AES-GCM, key derived from AUTH_SECRET) so lanyards can be
-- reprinted by authorised staff.
CREATE TABLE credentials (
  id                TEXT PRIMARY KEY,
  event_id          TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  registration_id   TEXT NOT NULL REFERENCES registrations(id) ON DELETE CASCADE,
  token_hash        TEXT NOT NULL UNIQUE,
  token_ciphertext  TEXT NOT NULL,
  short_code       TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  issued_at        TEXT NOT NULL,
  revoked_at       TEXT,
  UNIQUE (event_id, short_code)
);
CREATE UNIQUE INDEX credentials_one_active
  ON credentials (registration_id) WHERE status = 'active';

CREATE TABLE activity_bookings (
  activity_id      TEXT NOT NULL REFERENCES activities(id) ON DELETE CASCADE,
  registration_id  TEXT NOT NULL REFERENCES registrations(id) ON DELETE CASCADE,
  event_id         TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  source           TEXT NOT NULL CHECK (source IN ('manual', 'import', 'self_signup')),
  created_at       TEXT NOT NULL,
  PRIMARY KEY (activity_id, registration_id)
);

-- ---------------------------------------------------------------- scans

-- Append-only record of every scan. id is generated on the device, which makes
-- retried uploads idempotent. Corrections are new rows that supersede old ones.
CREATE TABLE scans (
  id                 TEXT PRIMARY KEY,
  event_id           TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  context_type       TEXT NOT NULL CHECK (context_type IN ('activity', 'meal', 'site')),
  context_id         TEXT,
  registration_id    TEXT REFERENCES registrations(id) ON DELETE CASCADE,
  credential_id      TEXT REFERENCES credentials(id) ON DELETE SET NULL,
  direction          TEXT NOT NULL CHECK (direction IN ('in', 'out')),
  method             TEXT NOT NULL CHECK (method IN ('qr', 'code', 'manual', 'correction')),
  device_time        TEXT NOT NULL,
  server_time        TEXT NOT NULL,
  device_id          TEXT NOT NULL,
  actor_user_id      TEXT REFERENCES users(id),
  actor_station_id   TEXT REFERENCES stations(id),
  outcome            TEXT NOT NULL CHECK (outcome IN ('accepted', 'duplicate', 'rejected', 'review', 'void')),
  outcome_reason     TEXT NOT NULL DEFAULT '',
  supersedes_id      TEXT REFERENCES scans(id),
  correction_reason  TEXT NOT NULL DEFAULT '',
  CHECK ((actor_user_id IS NULL) <> (actor_station_id IS NULL)),
  CHECK ((context_type = 'site') = (context_id IS NULL))
);
CREATE INDEX scans_context ON scans (event_id, context_type, context_id, registration_id, device_time);
CREATE INDEX scans_registration ON scans (registration_id, device_time);

CREATE TRIGGER scans_no_update BEFORE UPDATE ON scans
BEGIN
  SELECT RAISE(ABORT, 'scans are append-only');
END;

-- ---------------------------------------------------------------- imports

-- Summary only. Row data from source files is never stored.
CREATE TABLE import_jobs (
  id               TEXT PRIMARY KEY,
  event_id         TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  created_by       TEXT NOT NULL REFERENCES users(id),
  created_at       TEXT NOT NULL,
  source_label     TEXT NOT NULL DEFAULT '',
  rows_received    INTEGER NOT NULL DEFAULT 0,
  created_count    INTEGER NOT NULL DEFAULT 0,
  updated_count    INTEGER NOT NULL DEFAULT 0,
  unchanged_count  INTEGER NOT NULL DEFAULT 0,
  withdrawn_count  INTEGER NOT NULL DEFAULT 0,
  rejected_count   INTEGER NOT NULL DEFAULT 0
);

-- ---------------------------------------------------------------- audit

-- Append-only. detail must never contain sensitive values (dietary, contact).
CREATE TABLE audit_log (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  at           TEXT NOT NULL,
  actor_type   TEXT NOT NULL CHECK (actor_type IN ('user', 'station', 'system', 'public')),
  actor_id     TEXT,
  action       TEXT NOT NULL,
  event_id     TEXT,
  target_type  TEXT,
  target_id    TEXT,
  detail       TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX audit_log_event ON audit_log (event_id, at);
CREATE INDEX audit_log_at ON audit_log (at);

CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN
  SELECT RAISE(ABORT, 'audit_log is append-only');
END;

-- Deletion only once a record is past the 7-year retention period.
CREATE TRIGGER audit_log_no_early_delete BEFORE DELETE ON audit_log
WHEN OLD.at > strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-7 years')
BEGIN
  SELECT RAISE(ABORT, 'audit_log entries are retained for 7 years');
END;
